-- Locked front-desk tablet (Decisions 317, 320, 351; this build: Decision 380).
--
-- Staff start a FrontDeskSession for one Branch; the tablet then holds only the
-- session's token, never a staff login, and the API lets that token reach the
-- front-desk kiosk endpoints only. Leaving it takes a staff member's own kiosk
-- code (StaffKioskCode), generated by ULTM8, unique in the School.

ALTER TABLE "School" ADD COLUMN "checkInCodeDigits" INTEGER NOT NULL DEFAULT 4;
ALTER TABLE "School" ADD CONSTRAINT "School_checkInCodeDigits_check" CHECK ("checkInCodeDigits" IN (4, 6));

CREATE TABLE "FrontDeskSession" (
    "id" TEXT NOT NULL,
    "schoolId" TEXT NOT NULL,
    "branchId" TEXT,
    "startedById" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "expiresAt" TIMESTAMP(3) NOT NULL,
    "endedAt" TIMESTAMP(3),
    "endedById" TEXT,
    CONSTRAINT "FrontDeskSession_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "FrontDeskSession_schoolId_fkey" FOREIGN KEY ("schoolId") REFERENCES "School"("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "FrontDeskSession_branchId_fkey" FOREIGN KEY ("branchId") REFERENCES "Branch"("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "FrontDeskSession_startedById_fkey" FOREIGN KEY ("startedById") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "FrontDeskSession_endedById_fkey" FOREIGN KEY ("endedById") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE
);
CREATE INDEX "FrontDeskSession_schoolId_idx" ON "FrontDeskSession"("schoolId");
CREATE INDEX "FrontDeskSession_startedById_idx" ON "FrontDeskSession"("startedById");

CREATE TABLE "StaffKioskCode" (
    "id" TEXT NOT NULL,
    "schoolId" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "code" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "StaffKioskCode_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "StaffKioskCode_schoolId_fkey" FOREIGN KEY ("schoolId") REFERENCES "School"("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "StaffKioskCode_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE UNIQUE INDEX "StaffKioskCode_schoolId_userId_key" ON "StaffKioskCode"("schoolId", "userId");
CREATE UNIQUE INDEX "StaffKioskCode_schoolId_code_key" ON "StaffKioskCode"("schoolId", "code");
CREATE INDEX "StaffKioskCode_userId_idx" ON "StaffKioskCode"("userId");

GRANT SELECT, INSERT, UPDATE ON "FrontDeskSession" TO ultm8_app;
GRANT SELECT, INSERT, UPDATE ON "StaffKioskCode" TO ultm8_app;
-- The kiosk's own requests carry no user: the API reads the session, and the
-- code typed to leave, through ultm8_jobs.
GRANT SELECT ON "FrontDeskSession" TO ultm8_jobs;
GRANT SELECT ON "StaffKioskCode" TO ultm8_jobs;

ALTER TABLE "FrontDeskSession" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "FrontDeskSession" FORCE ROW LEVEL SECURITY;
ALTER TABLE "StaffKioskCode" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "StaffKioskCode" FORCE ROW LEVEL SECURITY;

-- Staff at the School see, start and end its tablets' sessions; a Branch-scoped
-- grant covers that Branch only. The subquery reads RoleGrant under its own RLS
-- (the caller's own grants), as student_home_branch_staff_read does.
CREATE POLICY "front_desk_session_staff" ON "FrontDeskSession"
  FOR ALL
  TO ultm8_app
  USING (
    EXISTS (
      SELECT 1 FROM "RoleGrant" rg
      WHERE rg."userId" = current_setting('app.current_user_id', true)
        AND rg."schoolId" = "FrontDeskSession"."schoolId"
        AND rg."role" IN ('SCHOOL_OWNER_MANAGER', 'BRANCH_STAFF', 'INSTRUCTOR')
        AND rg."revokedAt" IS NULL
        AND (rg."branchId" IS NULL OR rg."branchId" = "FrontDeskSession"."branchId")
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM "RoleGrant" rg
      WHERE rg."userId" = current_setting('app.current_user_id', true)
        AND rg."schoolId" = "FrontDeskSession"."schoolId"
        AND rg."role" IN ('SCHOOL_OWNER_MANAGER', 'BRANCH_STAFF', 'INSTRUCTOR')
        AND rg."revokedAt" IS NULL
        AND (rg."branchId" IS NULL OR rg."branchId" = "FrontDeskSession"."branchId")
    )
  );
CREATE POLICY "front_desk_session_jobs_read" ON "FrontDeskSession"
  FOR SELECT
  TO ultm8_jobs
  USING (true);

-- A staff member's own code only, at a School where they're staff.
CREATE POLICY "staff_kiosk_code_self" ON "StaffKioskCode"
  FOR ALL
  TO ultm8_app
  USING ("StaffKioskCode"."userId" = current_setting('app.current_user_id', true))
  WITH CHECK (
    "StaffKioskCode"."userId" = current_setting('app.current_user_id', true)
    AND EXISTS (
      SELECT 1 FROM "RoleGrant" rg
      WHERE rg."userId" = current_setting('app.current_user_id', true)
        AND rg."schoolId" = "StaffKioskCode"."schoolId"
        AND rg."role" IN ('SCHOOL_OWNER_MANAGER', 'BRANCH_STAFF', 'INSTRUCTOR')
        AND rg."revokedAt" IS NULL
    )
  );
CREATE POLICY "staff_kiosk_code_jobs_read" ON "StaffKioskCode"
  FOR SELECT
  TO ultm8_jobs
  USING (true);
